import{_ as o,o as a,c as t,a2 as d}from"./chunks/framework.CyZTVJbV.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.19/x-thread-ja.md","filePath":"announcements/v1.19/x-thread-ja.md"}'),r={name:"announcements/v1.19/x-thread-ja.md"};function c(n,e,s,i,l,p){return a(),t("div",null,[...e[0]||(e[0]=[d('<p>1/ kiwa v1.19 released。 Framework 深化 milestone です。 v1.18 (Blockchain 深化 縦軸、 Reth + Foundry invariant/fuzz + Alloy helpers + dApp reorg) の後、 v1.19 は modern web framework 3 種 (SolidJS (Signal-based fine-grained reactivity) + Deno Fresh (Islands architecture + partial hydration) + HonoJS (Cloudflare Workers + hc RPC type-safe client + middleware chain)) を横軸 reset milestone として同時 land しました。 kiwa web framework coverage を 8 → 11 に拡張します。</p><p>2/ <code>@kiwa-test/solidjs</code> v0.1.0 — SolidJS の Signal / Effect / createResource / Suspense boundary testing pattern。 <code>createSignal(initial)</code> で auto-tracking dependency graph mock、 <code>createEffect(fn)</code> は <code>flushSync()</code> deterministic scheduler で決定的、 <code>createResource(fetcher)</code> は <code>loading</code> / <code>error</code> / <code>latest</code> state の Suspense-aware async signal、 <code>SuspenseBoundary.captureFallback</code> + <code>resumeSuspense(id)</code> で boundary 遷移。 42 behavior test。</p><p>3/ <code>@kiwa-test/fresh</code> v0.1.0 — Deno Fresh Islands architecture testing pattern。 <code>defineRoute</code> で <code>{ handler, component }</code> shape normalize、 <code>Handler</code> union mock で <code>req</code> / <code>params</code> / <code>state</code> / <code>render</code> を Deno runtime なしで expose、 <code>renderIsland</code> は mount boundary + partial hydration markup を capture、 <code>Head</code> fragment merger は nested layout 越しの <code>&lt;meta&gt;</code> / <code>&lt;title&gt;</code> / <code>&lt;link&gt;</code> を dedupe。 58 behavior test。</p><p>4/ <code>@kiwa-test/hono</code> v0.1.0 — HonoJS Cloudflare Workers testing pattern。 <code>createApp()</code> で <code>.get / .post / .use</code> に一致する HonoLike stub、 <code>app.request(path, init)</code> で handler chain を Workers runtime なしで invoke、 <code>hc&lt;AppType&gt;(baseUrl)</code> は type-safe RPC client mock で <code>AppType</code> inference を end-to-end 保持、 <code>middlewareChain([cors, bearerAuth, logger])</code> は execution order + context state を <code>MiddlewareTrace</code> shape で trace、 <code>mockEnv({ KV, D1, R2, ExecutionContext })</code> で Workers env binding surface を提供。 89 behavior test。</p><p>5/ dogfood app 3 種 — <code>dogfood-solidjs-signal-app</code> (SolidJS + createResource + Suspense + fine-grained update × fidelity harness 5 scenario) + <code>dogfood-fresh-islands</code> (Deno Fresh + Islands + partial hydration + edge runtime × fidelity harness 5 scenario) + <code>dogfood-hono-workers-rpc</code> (Cloudflare Workers + Hono RPC + middleware chain + KV/D1/R2 bindings × fidelity harness 5 scenario)。 全 3 app が 7 軸 release gate PASS。</p><p>6/ 3 new npm package publish — <code>@kiwa-test/solidjs</code> v0.1.0 + <code>@kiwa-test/fresh</code> v0.1.0 + <code>@kiwa-test/hono</code> v0.1.0 を npm publish。 kiwa runtime fixture は 33 packages。 web framework coverage 8 → 11 (Next.js / Nuxt / SvelteKit / Remix / Astro / SolidStart / Qwik City / Edge + SolidJS / Fresh / HonoJS)。</p><p>7/ docs — tutorial 3 本 (28 SolidJS Signal / 29 Fresh Islands / 30 HonoJS + hc RPC + Workers env) + additive migration v1.18 → v1.19 + concept doc <code>modern-web-framework-testing.md</code> (Signal reactivity / Islands architecture / edge runtime + RPC type-safety の 3 追加軸 × 6 semantic axis SSOT)。 VitePress sidebar + gh-pages 反映済。 Roadmap: <a href="https://github.com/cardene777/kiwa#roadmap" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa#roadmap</a> — v1.11 → v1.12 → v1.13 → v1.14 → v1.15 → v1.16 → v1.17 → v1.18 → v1.19 の 9 milestone 連続完遂。</p>',7)])])}const m=o(r,[["render",c]]);export{h as __pageData,m as default};
